115	export function encodeCells(
116	  out: Uint8Array,
117	  width: number,
118	  bacterias: CellList,
119	  balance: GameBalance,
120	  box: CellBox
121	): void {
122	  const [x0, y0, x1, y1] = box;
123	  for (let y = y0; y < y1; y++) {
124	    out.fill(0, (y * width + x0) * 2, (y * width + x1) * 2);
125	  }
