127	  for (let i = 0; i < length; i++) {
128	    const x = xs[i];
129	    const y = ys[i];
130	    const energy = energies[i];
131	    if (x < x0 || x >= x1 || y < y0 || y >= y1) {
132	      continue;
133	    }
134	    const index = (y * width + x) * 2;
135	    out[index] = Math.round(255 * cellDensity(strengthOf(energy, balance)));
136	    out[index + 1] = Math.round(255 * overcharge(energy, balance));
137	  }
