454	  public paint(frame: ArenaFrame): void {
455	    const gl = this.gl;
456	    const resources = this.resources;
457	    const theme = this.theme;
458	    if (resources == null || theme == null) {
459	      return;
460	    }
461	    const { programs } = resources;
462	    this.motes.advance(frame.deltaTimeSec);
463	    this.weapons.update(frame);
464	    // Laid before the frame's own target is bound: no switch between them.
465	    this.layWalls(resources, frame.walls, theme);
466	    this.view = frame.view;
467	    // Every colony's cells and blur before the frame's own target is bound:
468	    // a GPU that renders in tiles stores and loads a target at each switch.
469	    const colonies = this.prepareColonies(resources, frame);
470	
471	    gl.bindFramebuffer(gl.FRAMEBUFFER, resources.trail.framebuffer);
472	    gl.viewport(0, 0, this.renderWidth, this.renderHeight);
473	    gl.enable(gl.BLEND);
474	    this.useAlphaBlend();
475	
476	    // Lay the floor over the previous frame, so movement leaves a short trail.
477	    this.useFullscreen(programs.floor);
478	    bindTexture(gl, 0, resources.floor, programs.floor.uniforms['uFloor']);
479	    this.setView(programs.floor);
480	    gl.uniform2f(programs.floor.uniforms['uArena'], this.width, this.height);
481	    // A target without a frame yet takes the floor whole, or it would show
482	    // the black it was cleared to through it.
483	    const floorAlpha = frame.clear || this.freshTrail ? 1 : 0.7;
484	    this.freshTrail = false;
485	    gl.uniform1f(programs.floor.uniforms['uAlpha'], floorAlpha);
486	    gl.uniform1i(
487	      programs.floor.uniforms['uHasZones'],
488	      resources.zones == null ? 0 : 1
489	    );
490	    if (resources.zones != null) {
491	      bindTexture(gl, 1, resources.zones, programs.floor.uniforms['uZones']);
492	    }
493	    gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
494	    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
495	    this.useAlphaBlend();
496	
497	    this.background.clear();
498	    pushMotes(this.background, theme, this.motes);
499	    this.drawShapes(this.background);
500	    this.drawWalls(resources);
501	    this.background.clear();
502	    pushDynamicWalls(this.background, theme, this.motes, frame.dynamicWalls);
503	    this.drawShapes(this.background);
504	    this.drawWeaponLayer(this.weapons.ground, false);
505	
506	    for (const colony of colonies) {
507	      this.drawColony(frame, colony);
508	    }
509	    if (!frame.reducedMotion) {
510	      this.drawEffects(frame);
511	    }
512	    // The weapons over the colonies - the clouds, the ice and the membrane,
513	    // then their flashes, shockwaves and sparks as light. The crosshairs
514	    // stay on top of it all.
515	    this.drawWeaponLayer(this.weapons.over, false);
516	    this.drawWeaponLayer(this.weapons.light, true);
517	
518	    this.foreground.clear();
519	    pushForeground(
520	      this.foreground,
521	      jamDrops(
522	        frame.nutrients,
523	        frame.balance.nutrientEnergy,
524	        frame.timeSec,
525	        this.unit
526	      ),
527	      frame.cursors,
528	      this.unit
529	    );
530	    this.drawShapes(this.foreground);
531	    this.ambience = frame.ambience ?? null;
532	    this.ambienceMoves = this.ambience != null && !frame.reducedMotion;
533	    this.packWisps(theme);
534	    this.showLastFrame();
535	  }
536	
537	  /** Copies the frame, kept in the trail, onto the canvas. */
538	  public showLastFrame(): void {
539	    const gl = this.gl;
540	    const resources = this.resources;
541	    if (resources == null) {
542	      return;
543	    }
544	    const { programs } = resources;
545	    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
546	    gl.viewport(0, 0, this.canvasWidth, this.canvasHeight);
547	    gl.disable(gl.BLEND);
548	    const blit = programs.blit;
549	    this.useFullscreen(blit);
550	    bindTexture(gl, 0, resources.trail.texture, blit.uniforms['uImage']);
551	    const ambience = this.ambience;
552	    gl.uniform1i(blit.uniforms['uDepth'], ambience == null ? 0 : 1);
553	    gl.uniform1i(blit.uniforms['uWispCount'], this.wispCount);
554	    if (this.wispCount > 0) {
555	      gl.uniform4fv(blit.uniforms['uWisps[0]'], this.wisps);
556	      gl.uniform3fv(blit.uniforms['uMist'], this.mist);
557	    }
558	    if (ambience != null) {
559	      this.setView(blit);
560	      gl.uniform2f(blit.uniforms['uArena'], this.width, this.height);
561	      gl.uniform1f(
562	        blit.uniforms['uReach'],
563	        AMBIENCE.rimWidth * Math.min(this.width, this.height)
564	      );
565	      gl.uniform2f(
566	        blit.uniforms['uCanvas'],
567	        this.canvasWidth,
568	        this.canvasHeight
569	      );
570	    }
571	    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
572	    if (ambience != null && this.ambienceMoves) {
573	      this.drawAmbience(ambience);
574	    }
575	  }
576	
577	  /**
578	   * Takes the frame's wisps of mist in view - none without the ambience's
579	   * motion.
580	   */
581	  private packWisps(theme: ArenaTheme): void {
582	    this.wispCount = 0;
583	    const ambience = this.ambience;
584	    if (ambience == null || !this.ambienceMoves) {
585	      return;
586	    }
587	    const wisps = this.wisps;
588	    ambience.forEachWisp(this.view, (x, y, radius, alpha) => {
589	      const at = this.wispCount++ * 4;
590	      wisps[at] = x;
591	      wisps[at + 1] = y;
592	      wisps[at + 2] = radius;
593	      wisps[at + 3] = alpha;
594	    });
595	    const [r, g, b] = theme.motes;
596	    this.mist[0] = r / 255;
597	    this.mist[1] = g / 255;
598	    this.mist[2] = b / 255;
599	  }
