601	  /** The ambience's bubbles, over the frame on the canvas. */
602	  private drawAmbience(ambience: DishAmbience): void {
603	    const gl = this.gl;
604	    gl.enable(gl.BLEND);
605	    this.useAlphaBlend();
606	    this.ambienceBatch.clear();
607	    pushAmbience(
608	      this.ambienceBatch,
609	      ambience,
610	      this.view,
611	      this.view.width / this.canvasWidth
612	    );
613	    this.drawShapes(this.ambienceBatch);
614	  }
