616	  /**
617	   * Lays the walls into their layer, as fine as the zones' - once per
618	   * level and look, the walls being the level's and never moving.
619	   */
620	  private layWalls(
621	    resources: Resources,
622	    walls: readonly Rect[],
623	    theme: ArenaTheme
624	  ): void {
625	    if (this.wallsFor?.walls === walls && this.wallsFor.theme === theme) {
626	      return;
627	    }
628	    this.wallsFor = { walls, theme };
629	    // A level without walls has no layer to lay - nor to draw.
630	    if (walls.length === 0) {
631	      return;
632	    }
633	    const gl = this.gl;
634	    const scale = layerScale(this.detail);
635	    const width = this.width * scale;
636	    const height = this.height * scale;
637	    resources.walls ??= createTarget(gl, gl.RGBA8, width, height, gl.LINEAR);
638	    gl.bindFramebuffer(gl.FRAMEBUFFER, resources.walls.framebuffer);
639	    gl.viewport(0, 0, width, height);
640	    gl.clearColor(0, 0, 0, 0);
641	    gl.clear(gl.COLOR_BUFFER_BIT);
642	    gl.enable(gl.BLEND);
643	    // Straight colours over a premultiplied layer leave it premultiplied.
644	    this.useAlphaBlend();
645	    this.background.clear();
646	    pushWalls(this.background, theme, walls);
647	    // All of the arena, row 0 of the layer at its top - as the zones' is.
648	    const view = this.view;
649	    this.view = {
650	      x: 0,
651	      y: this.height,
652	      width: this.width,
653	      height: -this.height,
654	    };
655	    this.drawShapes(this.background);
656	    this.view = view;
657	  }
658	
659	  /** The walls' layer over the floor and its specks. */
660	  private drawWalls(resources: Resources): void {
661	    const walls = resources.walls;
662	    if (walls == null || this.wallsFor?.walls.length === 0) {
663	      return;
664	    }
665	    const gl = this.gl;
666	    const program = resources.programs.walls;
667	    this.useFullscreen(program);
668	    bindTexture(gl, 0, walls.texture, program.uniforms['uWalls']);
669	    this.setView(program);
670	    gl.uniform2f(program.uniforms['uArena'], this.width, this.height);
671	    gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
672	    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
673	    this.useAlphaBlend();
674	  }
675	
676	  /**
677	   * Makes each colony in view ready to draw, in targets of its own: its
678	   * cells - uploaded from the CPU, or drawn straight from the GPU
679	   * simulation's state - blurred on the arena grid for every look but the
680	   * pixels.
681	   */
682	  private prepareColonies(
683	    resources: Resources,
684	    frame: ArenaFrame
685	  ): PreparedColony[] {
686	    const gl = this.gl;
687	    const prepared: PreparedColony[] = [];
688	    // Every pass here draws on the arena grid, unblended and scissored.
689	    gl.disable(gl.BLEND);
690	    gl.viewport(0, 0, this.width, this.height);
691	    gl.enable(gl.SCISSOR_TEST);
692	    frame.colonies.forEach((layer, index) => {
693	      const bounds =
694	        layer.kind === 'cells' ? colonyBounds(layer.cells) : layer.bounds;
695	      // A look that reaches past the colony - the lattice looks, with
696	      // their cells and tiles - is drawn that much further out, and every
697	      // pass before the drawing moves out with it, or it would read stale
698	      // density.
699	      const margin = passMargins(lookReach(layer.look, this.unit));
700	      if (bounds == null || !this.inView(bounds, margin.colony)) {
701	        return;
702	      }
703	      const targets = this.colonyTargets(resources, index);
704	      // Only the box around the colony, as far as it is in view, is
705	      // packed, blurred and drawn - the rest of the arena would be bytes to
706	      // upload and fragments the GPU works on to discard them.
707	      if (layer.kind === 'cells') {
708	        this.uploadCells(
709	          layer.cells,
710	          frame.balance,
711	          this.passBox(bounds, margin.cells),
712	          targets.cells
713	        );
714	      }
715	      if (layer.kind === 'state') {
716	        this.drawCellsFromState(
717	          layer,
718	          bounds,
719	          frame.balance,
720	          margin.cells,
721	          targets.cells
722	        );
723	      }
724	      if (LOOKS[layer.look].fromDensity) {
725	        this.useFullscreen(resources.programs.blur);
726	        this.scissorCells(bounds, margin.horizontalBlur);
727	        this.blurPass(targets.cells.texture, resources.blur, 1, 0);
728	        this.scissorCells(bounds, margin.verticalBlur);
729	        this.blurPass(resources.blur.texture, targets.density, 0, 1);
730	      }
731	      prepared.push({ layer, bounds, margin, targets });
732	    });
733	    gl.disable(gl.SCISSOR_TEST);
734	    return prepared;
735	  }
736	
737	  /** The targets of the colony at that place in the frame, made on first use. */
738	  private colonyTargets(resources: Resources, index: number): ColonyTargets {
739	    const gl = this.gl;
740	    const targets = resources.colonies;
741	    while (targets.length <= index) {
742	      targets.push({
743	        cells: createTarget(gl, gl.RG8, this.width, this.height),
744	        density: this.target(this.width, this.height, gl.LINEAR),
745	      });
746	    }
747	    return targets[index];
748	  }
749	
750	  /** One colony's pass over the frame, from its prepared cells and density. */
751	  private drawColony(frame: ArenaFrame, prepared: PreparedColony): void {
752	    const gl = this.gl;
753	    const resources = this.resources;
754	    if (resources == null) {
755	      return;
756	    }
757	    const { programs } = resources;
758	    const { layer, bounds, margin, targets } = prepared;
759	    const { color, boostTarget, look } = layer;
760	    gl.enable(gl.SCISSOR_TEST);
761	    this.scissorCanvas(bounds, margin.colony);
762	    const program = programs.colony;
763	    this.useFullscreen(program);
764	    bindTexture(gl, 0, targets.density.texture, program.uniforms['uDensity']);
765	    bindTexture(gl, 1, targets.cells.texture, program.uniforms['uCells']);
766	    this.setView(program);
767	    gl.uniform2f(program.uniforms['uArena'], this.width, this.height);
768	    const { rgb, alpha } = splitColor(color);
769	    gl.uniform3f(
770	      program.uniforms['uColor'],
771	      rgb[0] / 255,
772	      rgb[1] / 255,
773	      rgb[2] / 255
774	    );
775	    gl.uniform1f(program.uniforms['uAlpha'], alpha);
776	    gl.uniform1i(program.uniforms['uLook'], LOOKS[look].glIndex);
777	    gl.uniform1f(program.uniforms['uUnit'], this.unit);
778	    gl.uniform1f(
779	      program.uniforms['uPixel'],
780	      this.view.width / this.renderWidth
781	    );
782	    gl.uniform1f(program.uniforms['uTime'], frame.timeSec);
783	    const hatch = hatchPattern(color);
784	    gl.uniform3f(
785	      program.uniforms['uHatch'],
786	      hatch.direction[0],
787	      hatch.direction[1],
788	      hatch.cross ? 1 : 0
789	    );
790	    gl.uniform1f(
791	      program.uniforms['uShimmer'],
792	      boostTarget == null ? -1 : frame.timeSec
793	    );
794	    if (boostTarget != null) {
795	      gl.uniform2f(
796	        program.uniforms['uBoostTarget'],
797	        boostTarget.x,
798	        boostTarget.y
799	      );
800	    }
801	    const tints = packTints(
802	      this.weapons.tints,
803	      color,
804	      this.tintCircles,
805	      this.tintModes
806	    );
807	    gl.uniform1i(program.uniforms['uTintCount'], tints);
808	    if (tints > 0) {
809	      gl.uniform4fv(program.uniforms['uTints[0]'], this.tintCircles);
810	      gl.uniform4fv(program.uniforms['uTintModes'], this.tintModes);
811	    }
812	    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
813	    gl.disable(gl.SCISSOR_TEST);
814	  }
815	
816	  /** The colony's cells grown by a margin, clamped to the arena. */
817	  private box(bounds: CellBounds, margin: number): CellBox {
818	    return [
819	      Math.max(0, bounds.minX - margin),
820	      Math.max(0, bounds.minY - margin),
821	      Math.min(this.width, bounds.maxX + 1 + margin),
822	      Math.min(this.height, bounds.maxY + 1 + margin),
823	    ];
824	  }
825	
826	  /**
827	   * Scissors a pass on the frame's target, whose row 0 is the bottom of the
828	   * view - cut to the target, which a box out of view misses altogether.
829	   */
830	  private scissorCanvas(bounds: CellBounds, margin: number): void {
831	    const [x0, y0, x1, y1] = this.box(bounds, margin);
832	    const view = this.view;
833	    const width = this.renderWidth;
834	    const height = this.renderHeight;
835	    const scale = width / view.width;
836	    const clampX = (x: number) => Math.min(Math.max(x, 0), width);
837	    const clampY = (y: number) => Math.min(Math.max(y, 0), height);
838	    // Out to whole pixels - at a scale like 7.5 a cell edge falls inside one.
839	    const left = clampX(Math.floor((x0 - view.x) * scale));
840	    const right = clampX(Math.ceil((x1 - view.x) * scale));
841	    const bottom = clampY(Math.floor(height - (y1 - view.y) * scale));
842	    const top = clampY(Math.ceil(height - (y0 - view.y) * scale));
843	    this.gl.scissor(left, bottom, right - left, top - bottom);
844	  }
845	
846	  /** Hands a pass that draws onto the canvas the part of the arena it shows. */
847	  private setView(program: Program): void {
848	    const { x, y, width, height } = this.view;
849	    this.gl.uniform4f(program.uniforms['uView'], x, y, width, height);
850	  }
851	
852	  /** True when any of the colony's box, grown by the margin, is in view. */
853	  private inView(bounds: CellBounds, margin: number): boolean {
854	    const [x0, y0, x1, y1] = this.box(bounds, margin);
855	    const { x, y, width, height } = this.view;
856	    return x0 < x + width && x1 > x && y0 < y + height && y1 > y;
857	  }
858	
859	  /**
860	   * The colony's box grown by a margin, cut to the view grown by the same
861	   * margin: a pass on the arena grid only has to cover what the passes
862	   * after it read of the cells in view. The margins grow from one pass to
863	   * the one before it, so each still covers what the next one reads.
864	   */
865	  private passBox(bounds: CellBounds, margin: number): CellBox {
866	    const [x0, y0, x1, y1] = this.box(bounds, margin);
867	    const { x, y, width, height } = this.view;
868	    const left = Math.max(x0, Math.floor(x) - margin);
869	    const top = Math.max(y0, Math.floor(y) - margin);
870	    return [
871	      left,
872	      top,
873	      Math.max(left, Math.min(x1, Math.ceil(x + width) + margin)),
874	      Math.max(top, Math.min(y1, Math.ceil(y + height) + margin)),
875	    ];
876	  }
877	
878	  /** Scissors a pass on the arena grid - its row y is arena row y. */
879	  private scissorCells(bounds: CellBounds, margin: number): void {
880	    const [x0, y0, x1, y1] = this.passBox(bounds, margin);
881	    this.gl.scissor(x0, y0, x1 - x0, y1 - y0);
882	  }
883	
884	  /** Packs the box of a CPU colony into its cells texture and uploads it. */
885	  private uploadCells(
886	    bacterias: CellList,
887	    balance: GameBalance,
888	    box: CellBox,
889	    cells: Target
890	  ): void {
891	    const gl = this.gl;
892	    const [x0, y0, x1, y1] = box;
893	    encodeCells(this.cellBytes, this.width, bacterias, balance, box);
894	    if (x1 <= x0 || y1 <= y0) {
895	      return;
896	    }
897	    gl.activeTexture(gl.TEXTURE1);
898	    gl.bindTexture(gl.TEXTURE_2D, cells.texture);
899	    // The box's rows, out of the arena's.
900	    gl.pixelStorei(gl.UNPACK_ROW_LENGTH, this.width);
901	    gl.texSubImage2D(
902	      gl.TEXTURE_2D,
903	      0,
904	      x0,
905	      y0,
906	      x1 - x0,
907	      y1 - y0,
908	      gl.RG,
909	      gl.UNSIGNED_BYTE,
910	      this.cellBytes,
911	      (y0 * this.width + x0) * 2
912	    );
913	    gl.pixelStorei(gl.UNPACK_ROW_LENGTH, 0);
914	  }
915	
916	  /**
917	   * Draws a GPU colony's cells out of the simulation's state into the cells
918	   * texture - nothing crosses to the CPU. Only the box the blur reads is
919	   * drawn, all of it: cells of other colonies come out empty, so nothing
920	   * of them is left in there.
921	   */
922	  private drawCellsFromState(
923	    colony: StateLayer,
924	    bounds: CellBounds,
925	    balance: GameBalance,
926	    /** How far past the bounds to draw - what the horizontal blur reads. */
927	    margin: number,
928	    cells: Target
929	  ): void {
930	    const gl = this.gl;
931	    const resources = this.resources;
932	    if (resources == null) {
933	      return;
934	    }
935	    const program = resources.programs.cells;
936	    gl.bindFramebuffer(gl.FRAMEBUFFER, cells.framebuffer);
937	    this.scissorCells(bounds, margin);
938	    this.useFullscreen(program);
939	    bindTexture(gl, 0, colony.state, program.uniforms['uState']);
940	    gl.uniform1ui(program.uniforms['uOwner'], colony.owner);
941	    gl.uniform1f(program.uniforms['uMaxEnergy'], balance.maxEnergy);
942	    gl.uniform1f(
943	      program.uniforms['uSuperMaxEnergy'],
944	      balance.superChargedMaxEnergy
945	    );
946	    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
947	  }
948	
949	  /** Adds the glow of what the colonies do over them, light on light. */
950	  private drawEffects(frame: ArenaFrame): void {
951	    const gl = this.gl;
952	    const program = this.resources?.programs.effects;
953	    if (program == null) {
954	      return;
955	    }
956	    // Only around the colonies can anything glow - the box around all of
957	    // them spares the GPU the rest of the canvas.
958	    const colors = this.effectColors.fill(0);
959	    const around = emptyBounds();
960	    let effects: WebGLTexture | null = null;
961	    for (const layer of frame.colonies) {
962	      if (layer.kind !== 'state' || layer.bounds == null) {
963	        continue;
964	      }
965	      effects = layer.effects;
966	      colors.set(layer.color.slice(0, 3), (layer.owner - 1) * 3);
967	      const { minX, minY, maxX, maxY } = layer.bounds;
968	      growBounds(around, minX, minY, maxX, maxY);
969	    }
970	    if (effects == null) {
971	      return;
972	    }
973	    gl.enable(gl.SCISSOR_TEST);
974	    this.scissorCanvas(around, MARGIN.effects);
975	    this.useFullscreen(program);
976	    bindTexture(gl, 0, effects, program.uniforms['uEffects']);
977	    this.setView(program);
978	    gl.uniform2f(program.uniforms['uArena'], this.width, this.height);
979	    // The colours go as bytes - the shader scales them.
980	    gl.uniform3fv(program.uniforms['uColors[0]'], colors);
981	    gl.uniform1f(program.uniforms['uTime'], frame.timeSec);
982	    gl.blendFuncSeparate(gl.ONE, gl.ONE, gl.ZERO, gl.ONE);
983	    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
984	    gl.disable(gl.SCISSOR_TEST);
985	    this.useAlphaBlend();
986	  }
987	
988	  /** A layer of the weapons' marks - `light` adds it over the frame as light. */
989	  private drawWeaponLayer(layer: MarkLayer, light: boolean): void {
990	    if (layer.count === 0) {
991	      return;
992	    }
993	    const gl = this.gl;
994	    this.weaponBatch.clear();
995	    pushWeaponMarks(this.weaponBatch, layer);
996	    if (light) {
997	      gl.blendFuncSeparate(gl.SRC_ALPHA, gl.ONE, gl.ZERO, gl.ONE);
998	    }
999	    this.drawShapes(this.weaponBatch);
1000	    if (light) {
1001	      this.useAlphaBlend();
1002	    }
1003	  }
1004	
1005	  /** The blending everything but the glow is drawn with. */
1006	  private useAlphaBlend(): void {
1007	    const gl = this.gl;
1008	    gl.blendFuncSeparate(
1009	      gl.SRC_ALPHA,
1010	      gl.ONE_MINUS_SRC_ALPHA,
