    const gl = this.gl;
    const previous = resources.reports[this.reportIndex];
    this.reportIndex = 1 - this.reportIndex;
    gl.viewport(0, 0, layout.width, layout.height);
    bindTexture(
      gl,
      UNIT.events,
      resources.states[this.eventsIndex].texture,
      null
